async flushOdysseusIdleSessions(): Promise<void> {
  await Promise.all([...this.sessions.values()].filter(m => !m.isProcessing).map(m =>
    this.flushSession(m.id, m.workspace.id, {strict:true})))
}

/** Sessions with a runtime are never replaced by the external CLI mirror. */
getOdysseusProtectedSessions(): string[] {
  return [...this.sessions.values()]
    .filter(m => m.agent || m.isProcessing)
    .map(m => `${m.workspace.id}/${m.id}`)
}

/** Refresh only mirrors changed by Odysseus, without tearing down live agents. */
refreshOdysseusSessions(changes: {workspaceId: string; sessionId: string}[]): void {
  for (const workspace of this.listRuntimeWorkspaces()) {
    const ids = new Set(changes.filter(c => c.workspaceId === workspace.id).map(c => c.sessionId))
    if (!ids.size) continue
    for (const meta of this.sessionStore.list(workspace.id)) {
      if (!ids.has(meta.id)) continue
      const existing = this.getManaged(meta.id, workspace.id)
      if (existing?.agent || existing?.isProcessing) continue
      const managed = createManagedSession(meta, workspace, {
        enabledSourceSlugs: undefined, workingDirectory: meta.workingDirectory,
      })
      this.normalizePersistedSessionPermissionMode(managed)
      setPermissionMode({workspaceId: workspace.id, sessionId: meta.id}, managed.permissionMode ?? 'default', {changedBy: 'restore'})
      if (managed.previousPermissionMode) hydratePreviousPermissionMode({workspaceId: workspace.id, sessionId: meta.id}, managed.previousPermissionMode)
      this.sessions.set(this.managedKey(managed), managed)
      this.sendEvent({type: 'session_created', sessionId: meta.id}, workspace.id)
    }
  }
}

