  border: none !important;
}

/* ============================================================================
 * CONTAINER QUERY RESPONSIVE RULES
 *
 * These rules adapt component layout based on container width, replacing
 * the fragile !important overrides previously in webui/src/index.css.
 * Works in both webui (narrow viewport) and desktop (narrow panels).
 * ============================================================================ */

/* Constrain floating elements (dropdowns, selects) in narrow panel containers */
@container panel (max-width: 448px) {
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="select-content"] {
    max-width: calc(100cqw - 24px);
  }

  [data-slot="dropdown-menu-item"],
  [data-slot="dropdown-menu-sub-trigger"],
  [data-slot="select-item"] {
    min-width: 0;
  }

  [data-slot="dropdown-menu-item"] > span,
  [data-slot="dropdown-menu-sub-trigger"] > span,
  [data-slot="dropdown-menu-shortcut"],
  [data-slot="select-item"] {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

/* Settings rows: stack vertically in narrow panels.
   Toggle rows (anything containing a Switch) stay horizontal — iOS-style:
   label on the left, switch on the right. Stretching the switch to 100% width
   produced a long black pill bar that looked broken. */
@container panel (max-width: 448px) {
  [data-layout="settings-row"]:not(:has([data-slot="switch"])) {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
  }

  [data-layout="settings-row"]:not(:has([data-slot="switch"])) > [data-layout="settings-control"] {
    width: 100%;
    min-width: 0;
    margin-left: 0;
    flex-wrap: wrap;
    justify-content: flex-start;
  }

  /* Full-width form controls (selects, inputs) in stacked layout */
  [data-layout="settings-row"]:not(:has([data-slot="switch"])) [data-slot="select-trigger"],
  [data-layout="settings-row"]:not(:has([data-slot="switch"])) [data-layout="settings-control"] > .w-\[180px\],
  [data-layout="settings-row"]:not(:has([data-slot="switch"])) [data-layout="settings-control"] > .w-\[200px\] {
    width: 100%;
    max-width: 100%;
    min-width: 0;
  }
}

/* ==========================================================================
   1.3× touch target scaling on mobile (shell ≤ 768px)
   Formula: round(desktop_value × 1.3)
   ========================================================================== */
@container shell (max-width: 768px) {
  /* Panel header buttons: X, share, back chevron.
     Apple HIG minimum tap target is 44pt; min-width/height enforces the floor
     even if internal padding alone wouldn't reach it. */
  .panel-header-btn {
    padding: 10px;
    border-radius: 10px;
    min-width: 44px;
    min-height: 44px;
  }

  /* The back button starts at the panel edge (PanelHeader pl-0) and pads its 24px chevron 8px, so the
     chevron's INK (x 8–16 of the glyph) lands on the 16px gutter with the page content below. */
  .panel-header-btn.panel-header-back {
    padding-left: 8px;
    padding-right: 12px;
  }

  /* The chat header's status glyph groups with the title: a 36×44 target (8px around its 20px
     glyph) instead of a 44px square that pushed the title 30px away from the glyph. */
  .panel-header-btn.panel-header-status {
    min-width: 36px;
    padding-inline: 8px;
  }

  /* Compact panel header icons: keep desktop icons at their caller-provided
     size, but make compact-mode icons read clearly inside the 44px target. */
  [data-compact] .panel-header-btn > svg {
    width: 24px;
    height: 24px;
  }

  /* Session/source/skill list rows: touch height (desktop 36/54px → ≥ 60px), larger type */
  .entity-row-btn {
    min-height: 60px;
    padding-top: 11px;
    padding-bottom: 11px;
  }
  .entity-row-btn [data-slot="entity-row-title"] {
    font-size: var(--fs-copy);
    line-height: var(--lh-label-lg);
  }
  .entity-row-btn [data-slot="entity-row-subtitle"],
  .entity-row-btn [data-slot="entity-row-meta"] {
    font-size: var(--fs-label);
    line-height: var(--lh-label);
  }

  /* TopBar icon buttons: +, ?, nav arrows (desktop: 28×28 → 36×36) */
  .header-icon-btn {
    width: 36px;
    height: 36px;
  }

  /* IconButton primitive: 28px → 36px touch target */
  [data-slot="icon-button"] {
    width: 36px;
    height: 36px;
  }

  /* Input toolbar items: attach, task, workspace pill, model picker (desktop: h-7 = 28px → 36px) */
  .input-toolbar-btn {
    height: 36px;
    min-width: 36px;
  }

  /* Send button (desktop: 28×28 → 36×36) */
  .send-btn {
    width: 36px;
    height: 36px;
  }

  /* Settings form controls: 44px minimum height + 16px font.
     The 16px font-size prevents iOS Safari from auto-zooming into the field
     on focus (it triggers below 16px). Compact-only override so desktop stays
     at the original tighter sizing. */
  [data-layout="settings-row"] [data-slot="select-trigger"],
  [data-layout="settings-row"] [data-slot="input"],
  [data-layout="settings-row"] [data-slot="textarea"] {
    min-height: 44px;
    font-size: 16px;
  }

  /* Hover-reveal opt-in for touch.
     Components that use `opacity-0 group-hover:opacity-100` (more menus,
     row deletes, etc.) become invisible on touch — hover never fires.
     Adding `data-touch-reveal="true"` opts the element into always-visible
     in compact. Desktop keeps the hover-reveal behavior unchanged.
     `!important` is necessary to beat Tailwind's `opacity-0` utility. */
  [data-touch-reveal="true"] {
    opacity: 1 !important;
  }

  /* Bottom safe area for iOS home indicator + FAB clearance.
     Sessions list keeps a 72px buffer (FAB is ~56px + bottom inset 16px)
     so the last row never sits underneath the floating action button.
     Other list roles (sources/skills/automations) only need the iOS
     safe-area inset since they don't have a FAB. */
  [data-list-role] {
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }
  [data-list-role="sessions"] {
    padding-bottom: calc(72px + env(safe-area-inset-bottom, 0px));
  }

  /* Top safe area: keep the navigator's first row clear of the iOS notch
     when the app runs as a PWA / mobile webui. Desktop builds report 0px
     for the inset so this is a no-op there. */
  [data-panel-role="navigator"] {
    padding-top: env(safe-area-inset-top, 0px);
  }

  /* Workspace pill chevron: 12px is hard to read at narrow widths,
     bump to 16px so the dropdown affordance is clearly tappable. */
  [data-workspace-switcher="topbar"] [data-slot="chevron"] {
    width: 16px;
    height: 16px;
  }
}

/* TopBar lives outside the shell container, so the workspace pill chevron
   needs a viewport-media equivalent for the topbar variant specifically. */
@media (max-width: 768px) {
  /* TopBar lives outside the shell container, so mirror the compact 36px
     button target here instead of relying only on @container shell rules. */
  .header-icon-btn {
    width: 36px;
    height: 36px;
    border-radius: 8px;
  }

  [data-workspace-switcher="topbar"] [data-slot="chevron"] {
    width: 16px;
    height: 16px;
  }
}

/* ==========================================================================
   TopBar height — bumps to 56px on narrow viewports so it matches the larger
   touch targets and feels less cramped on mobile. The TopBar uses position:
   fixed so the App content area reads the same variable for its padding-top.
   ========================================================================== */
:root {
  --topbar-height: 44px;
}
@media (max-width: 768px) {
  :root {
    --topbar-height: 56px;
  }

  /* Bump TopBar icons from 18px → 20px in compact mode. Kept tight inside the
     36×36 button so it doesn't dominate the bar. */
  .header-icon-btn svg {
    width: 20px;
    height: 20px;
  }
}

/* TurnCard action buttons (Copy, Markdown) — outside @container/shell,
   scaled via data-compact attribute passed from the renderer */
[data-compact] .turn-action-btn {
  min-height: 31px;
  padding: 6px 8px;
}

/* Odysseus identity: restrained bronze, original knight portrait, no animated background. */
.odysseus-portrait { position:relative; width:min(360px,70vw); height:220px; margin-bottom:20px; overflow:hidden; border-radius:20px; background:#080909; border:1px solid #a9936a55; box-shadow:0 18px 60px #0002; }
.odysseus-portrait img { width:100%; height:100%; object-fit:cover; object-position:48% 32%; opacity:.9; }
.odysseus-portrait::after { content:''; position:absolute; inset:0; background:linear-gradient(0deg,#080909 0%,transparent 58%); pointer-events:none; }
.odysseus-wordmark { position:absolute; bottom:18px; left:0; right:0; z-index:1; color:#e4d6ba; letter-spacing:.32em; font-size:14px; font-weight:600; }
.odysseus-portrait-compact { width:250px; height:155px; margin-bottom:12px; }
@media(max-height:650px) { .odysseus-portrait { height:135px; width:240px; margin-bottom:8px; } }

